import sys
from collections import defaultdict

MOD = 1000000007

class ModInt:
    __slots__ = ('v',)
    def __init__(self, v=0):
        self.v = v % MOD
    def __add__(self, other):
        if isinstance(other, ModInt):
            return ModInt(self.v + other.v)
        return ModInt(self.v + other)
    def __radd__(self, other):
        return ModInt(other + self.v)
    def __sub__(self, other):
        if isinstance(other, ModInt):
            return ModInt(self.v - other.v)
        return ModInt(self.v - other)
    def __rsub__(self, other):
        return ModInt(other - self.v)
    def __mul__(self, other):
        if isinstance(other, ModInt):
            return ModInt(self.v * other.v)
        return ModInt(self.v * other)
    def __rmul__(self, other):
        return ModInt(other * self.v)
    def __truediv__(self, other):
        if isinstance(other, ModInt):
            return ModInt(self.v * pow(other.v, MOD-2, MOD))
        return ModInt(self.v * pow(other % MOD, MOD-2, MOD))
    def __iadd__(self, other):
        if isinstance(other, ModInt):
            self.v = (self.v + other.v) % MOD
        else:
            self.v = (self.v + other) % MOD
        return self
    def __imul__(self, other):
        if isinstance(other, ModInt):
            self.v = (self.v * other.v) % MOD
        else:
            self.v = (self.v * other) % MOD
        return self
    def __repr__(self):
        return str(self.v)
    def __eq__(self, other):
        if isinstance(other, ModInt):
            return self.v == other.v
        return self.v == other

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    P = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            P[i][j] = int(next(it))

    S = 128  # just for reference, we use integer bitsets
    # G: map from integer (bitset of masks) to ModInt
    G = {1: ModInt(1)}
    for i in range(N):
        # Convert G to H: map from sorted list of masks to ModInt
        H = {}
        for bitset_val, val in G.items():
            masks = [m for m in range(1<<N) if (bitset_val >> m) & 1]
            # sort (already in increasing order)
            H[tuple(masks)] = val  # use tuple as key
        G.clear()
        for j in range(1<<N):
            pst = ModInt(1)
            for k in range(N):
                if (j>>k) & 1:
                    pst *= P[i][k]
                else:
                    pst *= (100 - P[i][k])
            for masks, h_val in H.items():
                ans = 0
                for l in range(N):
                    if (j>>l) & 1:
                        for m in masks:
                            if not ((m>>l) & 1):
                                new_mask = m | (1<<l)
                                ans |= (1 << new_mask)
                if ans != 0:
                    if ans not in G:
                        G[ans] = ModInt(0)
                    G[ans] += h_val * pst

    total = ModInt(0)
    for val in G.values():
        total += val
    # divide by 100^(N*N)
    divisor = pow(100, N*N, MOD)
    total = total / divisor
    print(total)

if __name__ == "__main__":
    solve()
